/**
 * ToggleGroup — generated by the React Native Reusables CLI (`toggle-group`), re-skinned.
 *
 * Deviations from upstream, kept here so the next `add toggle-group --overwrite` diff reads:
 * - It draws as a segmented control: the group is a `muted` track with a hairline
 *   edge, and each item a `rounded-sm` segment inside it. Upstream butts the items
 *   together and rounds only the ends, so its `isFirst` / `isLast` props are gone.
 * - The selected segment is the toggle's pressed face (`togglePressedClass`): a
 *   `card` segment with a strong hairline and a full-ink label, lifted off its
 *   track at `sm` through `useElevation` — the step the guidelines name for a
 *   selected segment. A readout, not an accent fill, so the group never spends
 *   the screen's one accent.
 * - `shadow-sm shadow-black/5` is gone from the outline group: opacity modifiers
 *   do nothing on hex variables, and NativeWind's `shadow-*` cannot carry the
 *   per-theme layers that `boxShadow` does.
 * - Items share the track's width (`flex-1`, `px-1`) on every platform, not just web: three
 *   choices on a phone read as one row of equal segments.
 */
import { Icon } from '@/components/ui/icon';
import { TextClassContext } from '@/components/ui/text';
import { togglePressedClass, toggleTextClass, toggleVariants } from '@/components/ui/toggle';
import { cn } from '@/lib/utils';
import { useElevation } from '@/ui/elevation';
import * as ToggleGroupPrimitive from '@rn-primitives/toggle-group';
import type { VariantProps } from 'class-variance-authority';
import * as React from 'react';
import { Platform } from 'react-native';

const ToggleGroupContext = React.createContext<VariantProps<typeof toggleVariants> | null>(null);

function ToggleGroup({
  className,
  variant,
  size,
  children,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Root> & VariantProps<typeof toggleVariants>) {
  return (
    <ToggleGroupPrimitive.Root
      className={cn(
        'flex flex-row items-center gap-1 rounded-md border border-border bg-muted p-1',
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive.Root>
  );
}

function useToggleGroupContext() {
  const context = React.useContext(ToggleGroupContext);
  if (context === null) {
    throw new Error(
      'ToggleGroup compound components cannot be rendered outside the ToggleGroup component',
    );
  }
  return context;
}

function ToggleGroupItem({
  className,
  children,
  variant,
  size,
  style,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Item> & VariantProps<typeof toggleVariants>) {
  const context = useToggleGroupContext();
  const lift = useElevation('sm');
  const { value } = ToggleGroupPrimitive.useRootContext();
  const selected = ToggleGroupPrimitive.utils.getIsSelected(value, props.value);

  return (
    <TextClassContext.Provider value={toggleTextClass(selected)}>
      <ToggleGroupPrimitive.Item
        className={cn(
          toggleVariants({
            variant: context.variant || variant,
            size: context.size || size,
          }),
          // A third of a phone width holds "Match system" only with the side padding
          // cut to the smallest step.
          'min-w-0 flex-1 rounded-sm px-1',
          props.disabled && 'opacity-50',
          selected && togglePressedClass,
          Platform.select({ web: 'focus:z-10 focus-visible:z-10' }),
          className,
        )}
        style={
          selected
            ? typeof style === 'function'
              ? (state) => [lift, style(state)]
              : [lift, style]
            : style
        }
        {...props}
      >
        {children}
      </ToggleGroupPrimitive.Item>
    </TextClassContext.Provider>
  );
}

function ToggleGroupIcon({ className, ...props }: React.ComponentProps<typeof Icon>) {
  const textClass = React.useContext(TextClassContext);
  return <Icon className={cn('size-4 shrink-0', textClass, className)} {...props} />;
}

export { ToggleGroup, ToggleGroupIcon, ToggleGroupItem };
